from typing import Dict, Iterable, List, Mapping, Tuple, Set

from stockflow.on_hand_by_location import on_hand_by_location
from stockflow.normalize_sku import normalize_sku
from stockflow.parse_location import parse_location


def _format_location(parsed: Tuple[str, int, int, int]) -> str:
    zone, aisle, shelf, level = parsed
    return f"{zone}-{aisle:02d}-{shelf:02d}-{level}"


def cycle_count_variance(lines: Iterable[str], case_sizes: Mapping[str, int], counts: Mapping[Tuple[str, str], int]) -> List[Tuple[str, str, int]]:
    system_stock: Dict[Tuple[str, str], int] = on_hand_by_location(lines, case_sizes)
    normalized_counts: Dict[Tuple[str, str], int] = {}
    for (raw_sku, raw_loc), qty in counts.items():
        if qty < 0:
            raise ValueError(f"Counted quantity cannot be negative: {qty}")
        canon_sku = normalize_sku(raw_sku)
        parsed_loc = parse_location(raw_loc)
        canon_loc = _format_location(parsed_loc)
        key = (canon_sku, canon_loc)
        normalized_counts[key] = normalized_counts.get(key, 0) + qty
    counted_locations: Set[str] = set(loc for (sku, loc) in normalized_counts.keys())
    results: Dict[Tuple[str, str], int] = {}
    for (sku, loc), counted_qty in normalized_counts.items():
        system_qty = system_stock.get((sku, loc), 0)
        variance = counted_qty - system_qty
        if variance != 0:
            results[(sku, loc)] = variance
    for (sku, loc), sys_qty in system_stock.items():
        if loc in counted_locations and (sku, loc) not in normalized_counts:
            variance = 0 - sys_qty
            if variance != 0:
                results[(sku, loc)] = variance
    sorted_results = sorted(results.items(), key=lambda x: (x[0][1], x[0][0]))
    return [(sku, loc, var) for (sku, loc), var in sorted_results]
