    for bin_items in bins:
        parcel: Dict[str, int] = {}
        for sku, weight in bin_items:
            unit_weight = sku_weights[sku]
            units = weight // unit_weight
            parcel[sku] = parcel.get(sku, 0) + units
        result.append(parcel)

    return result
